from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(data[j], data[j + 1]):
                    self.swap(data, j, j + 1)
        return data

    @abstractmethod
    def compare(self, a, b): pass

    @abstractmethod
    def swap(self, data, i, j): pass

class BubbleSort(SortAlgorithm):
    def compare(self, a, b): return a > b
    def swap(self, data, i, j): data[i], data[j] = data[j], data[i]

class SelectionSort(SortAlgorithm):
    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(data[min_idx], data[j]):
                    min_idx = j
            self.swap(data, i, min_idx)
        return data
    def compare(self, a, b): return a > b
    def swap(self, data, i, j): data[i], data[j] = data[j], data[i]

# Testing
