    Car(std::string b, int y, float w, int d, std::string f) : Vehicle(b, y, w), doors(d), fuelType(f), isAutomatic(true) {}
    void displayInfo() override { std::cout << "Car: " << brand << " (" << year << "), Doors: " << doors << "\n"; }
};

