    std::string engineType;
public:
    Airplane(std::string b, int y, float w, int ws, int alt) : Vehicle(b, y, w), wingspan(ws), maxAltitude(alt), engineType("Jet") {}
    void displayInfo() override { std::cout << "Airplane: " << brand << " (" << year << "), Wingspan: " << wingspan << "\n"; }
};

